package com.autoops.dataset.controller;import com.autoops.dataset.entity.DatasetImport;import com.autoops.dataset.service.DatasetImportService;import org.springframework.web.bind.annotation.*;import java.util.List;@RestController @RequestMapping("/api/admin/datasets")public class DatasetImportController{private final DatasetImportService service;public DatasetImportController(DatasetImportService s){service=s;}@PostMapping("/{id}/import")public DatasetImport run(@PathVariable Long id,@RequestBody List<DatasetImportService.Row> rows){return service.importRows(id,rows);}}
